<?php require_once "db.php"; $msg=""; if($_SERVER["REQUEST_METHOD"]==="POST"){ $n=trim($_POST["name"]);$e=trim($_POST["email"]);$p=password_hash($_POST["password"],PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(name,email,password) VALUES(?,?,?)");$s->bind_param("sss",$n,$e,$p);$msg=$s->execute()?"Registration successful.":"Email already registered."; } ?>
<!doctype html><html><head><title>Register</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="container formbox"><h2>Create Account</h2><p><?=htmlspecialchars($msg)?></p><form method="post"><input name="name" placeholder="Full name" required><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button class="btn">Register</button></form><a href="login.php">Login</a></main></body></html>